--=================================================================================================
--= Loot drops data (English)
--= ===============================================================================================
--= GENERATED FROM THE GAME'S OWN LOOT TABLES. Do not hand-edit: rebuild it instead.
--=
--=     cd ../LootScribe && python3 tools/csv_to_drops.py --=         ../LootLogs/LootTables/*.csv > ../LootLogs/Logs/Drops/English.lua
--=
--= The script lives in the LootScribe plugin and documents the CSV format it reads; the CSVs
--= themselves are kept in LootLogs/LootTables/, which is gitignored and has its own README.
--=
--= Keyed by _G.Events index, so a chest's loot table is a direct lookup from the index
--= ProcessMatch already produced. Because _G.Events has one entry per (boss, tier) pair,
--= per-tier drop chances come for free -- there is no nested tier table here.
--=
--= LAID OUT THE WAY THE WINDOW READS. Instances in the sidebar's order (newest content pack
--= first), each one's tiers lowest first the way the pills run, each tier's chests in sidebar
--= order, and inside a chest ONE ROW PER ITEM, likeliest first. The file walks the browser.
--=
--= ONE ROW PER ITEM, FOLDED HERE RATHER THAN AT LOAD. The game's tables list an item once per
--= pool it sits in, so a chest is three hundred entries for ninety items and the same cloak
--= appears eight times at eight rates. A pool is a roll, not a thing that drops -- nobody loots
--= "the gear table" -- so the pools are folded away and what is left is the item:
--=
--= chance  : 0..1, the chance it drops AT ALL from this chest: 1 - the product of (1 - c) over
--=           its entries. NOT their sum, which would put a six-pool item past 100%, and not the
--=           biggest of them, because sitting in six pools is what makes it likelier. Absent
--=           means "drops, rate not established" and must never be shown as 0%.
--= chances : OPTIONAL, the individual rates behind that figure, biggest first. ABSENT for an
--=           item with only one, because then `chance` already is that number.
--=
--= item    : the NORMALISED base name, exactly as chat prints it, WITHOUT a quantity prefix and
--=           WITHOUT a ", Lvl NNN" suffix. THE KEY, and the only thing the parser matches on.
--= plural  : OPTIONAL, the spelling used when more than one drops at once. Cannot be derived by
--=           rule ("Badges of Forgotten Rank"), and the CSV does not carry it, so it is filled
--=           in from a capture.
--= label   : OPTIONAL, what to CALL the item on screen. Display only; `item` stays the key.
--= quality : OPTIONAL, "incomparable" | "rare" | "uncommon" | "common".
--= slot    : OPTIONAL free text for the browser's slot column.
--= popup   : true means worth interrupting the player for, and it is the ONLY thing the loot
--=           popup shows. A DISPLAY filter: every catalogued drop is still counted.
--= id      : the item id. A quickslot shortcut built as "0x0000000000000000,0x<id>" resolves
--=           even for an item nobody owns, which is what draws the row's real icon, and the
--=           same id builds the clickable chat link.
--= category: OPTIONAL, this row names a CATEGORY rather than an item -- see "?? " below.
--=
--= WHERE THE NUMBERS COME FROM. The CSV is the game's own table, so a chance here is not an
--= observation and not a community estimate -- it is the rate the server rolls. Three shapes
--= go into the fold:
--=
--=     a weighted entry   its table's chance times its share of that table
--=                        (a 5% table, a 90% share -> 4.5%)
--=     a lone entry       its own chance, straight out of the file
--=     a guaranteed one   1.00, and the file gives it no id
--=
--= Each chest lists three armour-weight variants of the same table, filtered to your class, so
--= exactly one applies. An exact repeat -- the same roll written out three times -- is one
--= entry; anything that differs is a separate chance at the item and is kept.
--=
--= A "?? " NAME IS A CATEGORY, NOT AN ITEM, and carries `category = true`. "?? Tracery" is what
--= the tables say about traceries: everyone gets one, and chat prints the rolled name instead,
--= so the row can never match a loot line. It is drawn under its `label`.
--=
--= The keys are shared with German.lua and French.lua -- those files translate the item NAMES
--= only and must never re-key.
--=================================================================================================

